1	import { CATALOG } from "./catalog";
2	import { getDetail } from "./details";
3	import { getCategory } from "./questions";
4	import type { Answers, CategoryId, Recommendation } from "./types";
5	
6	const GENERIC_REASON = "A strong general-purpose choice for this layer";
7	
8	/**
9	 * Score every candidate in every layer and build the recommendation.
10	 *
11	 * For each candidate: total = base + sum(boost.score) for boosts whose
12	 * `when(answers)` is true. The top scorer becomes the primary pick; the
13	 * reasons shown are the positive boosts that fired for it. The next two
14	 * candidates that scored above zero are offered as alternatives, and the
15	 * full ranked list is exposed for transparency.
16	 */
17	export function recommend(categoryId: CategoryId, answers: Answers): Recommendation {
18	  const category = getCategory(categoryId);
19	  if (!category) {
20	    throw new Error(`Unknown category: ${categoryId}`);
21	  }
22	
23	  const layers = category.layers.map((layer) => {
24	    const scored = layer.candidates
25	      .map((candidate) => {
26	        const reasons: string[] = [];
27	        let score = candidate.base;
28	        for (const boost of candidate.boosts ?? []) {
29	          if (boost.when(answers)) {
30	            score += boost.score;
31	            // Surface the rationale for any boost that fires and carries text.
32	            // Penalty boosts (negative score) intentionally use an empty reason,
33	            // while an always-on note can use score 0 to add context without points.
34	            if (boost.score >= 0 && boost.reason) {
35	              reasons.push(boost.reason);
36	            }
37	          }
38	        }
39	        return { tech: candidate.tech, score, reasons };
40	      })
41	      // Stable, deterministic ordering: score desc, then declaration order.
42	      .map((entry, index) => ({ ...entry, index }))
43	      .sort((a, b) => b.score - a.score || a.index - b.index);
44	
45	    const top = scored[0];
46	    const topTech = CATALOG[top.tech];
47	    const detail = getDetail(top.tech);
48	    const reasons = top.reasons.length > 0 ? top.reasons : [GENERIC_REASON];
49	
50	    const alternatives = scored
51	      .slice(1)
52	      .filter((s) => s.score > 0)
53	      .slice(0, 2)
54	      .map((s) => ({ name: CATALOG[s.tech].name, url: CATALOG[s.tech].url }));
55	
56	    const ranked = scored.map((s) => ({
57	      name: CATALOG[s.tech].name,
58	      url: CATALOG[s.tech].url,
59	      score: s.score,
60	    }));
61	
62	    return {
63	      layer: layer.label,
64	      key: layer.key,
65	      primary: {
66	        name: topTech.name,
67	        blurb: topTech.blurb,
68	        url: topTech.url,
69	        reasons,
70	        pros: detail.pros,
71	        cons: detail.cons,
72	        getStarted: detail.getStarted,
73	        score: top.score,
74	      },
75	      alternatives,
76	      ranked,
77	    };
78	  });
79	
80	  return {
81	    categoryId,
82	    categoryLabel: category.label,
83	    layers,
84	    summary: layers.map((l) => ({ layer: l.layer, tech: l.primary.name })),
85	  };
86	}
87	
88	/** The non-empty getting-started commands for the recommended picks. */
89	export function scaffoldCommands(
90	  rec: Recommendation,
91	): { layer: string; name: string; command: string }[] {
92	  return rec.layers
93	    .filter((l) => l.primary.getStarted.trim().length > 0)
94	    .map((l) => ({ layer: l.layer, name: l.primary.name, command: l.primary.getStarted }));
95	}
96	
97	/** Plain-text version of a recommendation, for copy-to-clipboard. */
98	export function recommendationToText(rec: Recommendation): string {
99	  const lines: string[] = [
100	    `Recommended stack — ${rec.categoryLabel}`,
101	    "",
102	    ...rec.summary.map((s) => `• ${s.layer}: ${s.tech}`),
103	    "",
104	    "Generated by TechStack Advisor",
105	  ];
106	  return lines.join("\n");
107	}
108	
109	/** Markdown version of a recommendation, for export/download. */
110	export function recommendationToMarkdown(rec: Recommendation): string {
111	  const lines: string[] = [`# Recommended stack — ${rec.categoryLabel}`, ""];
112	
113	  lines.push("| Layer | Pick |", "| --- | --- |");
114	  for (const s of rec.summary) lines.push(`| ${s.layer} | ${s.tech} |`);
115	  lines.push("");
116	
117	  for (const layer of rec.layers) {
118	    lines.push(`## ${layer.layer}: [${layer.primary.name}](${layer.primary.url})`, "");
119	    lines.push(`${layer.primary.blurb}`, "");
120	    if (layer.primary.reasons.length) {
121	      lines.push("**Why:**");
122	      for (const r of layer.primary.reasons) lines.push(`- ${r}`);
123	      lines.push("");
124	    }
125	    if (layer.primary.pros.length) {
126	      lines.push("**Strengths:** " + layer.primary.pros.join(" · "), "");
127	    }
128	    if (layer.primary.cons.length) {
129	      lines.push("**Watch-outs:** " + layer.primary.cons.join(" · "), "");
130	    }
131	    if (layer.primary.getStarted) {
132	      lines.push("```bash", layer.primary.getStarted, "```", "");
133	    }
134	    if (layer.alternatives.length) {
135	      lines.push(
136	        "_Also consider: " +
137	          layer.alternatives.map((a) => `[${a.name}](${a.url})`).join(", ") +
138	          "_",
139	        "",
140	      );
141	    }
142	  }
143	
144	  const scaffold = scaffoldCommands(rec);
145	  if (scaffold.length) {
146	    lines.push("## Getting started", "", "```bash");
147	    for (const s of scaffold) lines.push(`# ${s.name}`, s.command);
148	    lines.push("```", "");
149	  }
150	
151	  lines.push("---", "_Generated by TechStack Advisor_");
152	  return lines.join("\n");
153	}
